    "lt_skills_title": "I tuoi risultati",
    "lt_skill_grammar": "Grammatica",
    "lt_skill_vocabulary": "Lessico",
    "lt_skill_reading": "Comprensione scritta",
    "lt_focus": "Su cosa lavoreremo",
    "lt_cta": "Crea il tuo account gratuito",
